import{_ as s,a0 as i,w as p,s as l,ao as n,I as a,x as e,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170214 How to Install Ubuntu with Separate Root and Home Hard Drives","title":"在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu","tag":"201703","desc":""},"relativePath":"201703/20170214 How to Install Ubuntu with Separate Root and Home Hard Drives.md","filePath":"[post].md"}'),d={name:"201703/20170214 How to Install Ubuntu with Separate Root and Home Hard Drives.md"};function b(m,t,h,f,U,T){const u=i("Link");return p(),l("div",null,[t[18]||(t[18]=n('<h1 id="在独立的-root-和-home-硬盘驱动器上安装-ubuntu" tabindex="-1">在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu <a class="header-anchor" href="#在独立的-root-和-home-硬盘驱动器上安装-ubuntu" aria-label="Permalink to “在独立的 Root 和 Home 硬盘驱动器上安装 Ubuntu”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/ubuntu-feature-image.jpg" alt="" title="How to Install Ubuntu with Separate Root and Home Hard Drivess"></p><p>安装 Linux 系统时，可以有两种不同的方式。第一种方式是在一个超快的固态硬盘上进行安装，这样可以保证迅速开机和高速访问数据。第二种方式是在一个较慢但很强大的普通硬盘驱动器上安装，这样的硬盘转速快并且存储容量大，从而可以存储大量的应用程序和数据。</p><p>然而，一些 Linux 用户都知道，固态硬盘很棒，但是又很贵，而普通硬盘容量很大但速度较慢。如果我告诉你，可以同时利用两种硬盘来安装 Linux 系统，会怎么样？一个超快、现代化的固态硬盘驱动 Linux 内核，一个容量很大的普通硬盘来存储其他数据。</p><p>在这篇文章中，我将阐述如何通过分离 Root 目录和 Home 目录安装 Ubuntu 系统 — Root 目录存于 SSD（固态硬盘）中，Home 目录存于普通硬盘中。</p><h3 id="没有多余的硬盘驱动器-尝试一下-sd-卡-内存卡" tabindex="-1">没有多余的硬盘驱动器？尝试一下 SD 卡（内存卡）！ <a class="header-anchor" href="#没有多余的硬盘驱动器-尝试一下-sd-卡-内存卡" aria-label="Permalink to “没有多余的硬盘驱动器？尝试一下 SD 卡（内存卡）！”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/ubuntu-sd-card.jpg" alt="ubuntu-sd-card" title="ubuntu-sd-card"></p><p>在多个驱动器上安装 Linux 系统是很不错的，并且每一个高级用户都应该学会这样做。然而，还有一种情况使得用户应该这样安装 Linux 系统 － 在低存储容量的笔记本电脑上安装系统。可能你有一台很便宜、没有花费太多的笔记本电脑，上面安装了 Linux 系统，电脑上没有多余的硬盘驱动，但有一个 SD 卡插槽。</p><p>这篇教程也是针对这种类型的电脑的。跟随这篇教程，可以为笔记本电脑买一个高速的 SD 卡来存储 Home 目录，而不是使用另一个硬盘驱动。本教程也适用于这种使用情况。</p><h3 id="制作-usb-启动盘" tabindex="-1">制作 USB 启动盘 <a class="header-anchor" href="#制作-usb-启动盘" aria-label="Permalink to “制作 USB 启动盘”">​</a></h3>',10)),a("p",null,[t[2]||(t[2]=e("首先去",-1)),o(u,{href:"http://ubuntu.com/download"},{default:r(()=>[...t[0]||(t[0]=[e("这个网站",-1)])]),_:1}),t[3]||(t[3]=e("下载最新的 Ubuntu Linux 版本。然后下载 ",-1)),o(u,{href:"https://etcher.io/"},{default:r(()=>[...t[1]||(t[1]=[e("Etcher",-1)])]),_:1}),t[4]||(t[4]=e("- USB 镜像制作工具。这是一个使用起来很简单的工具，并且支持所有主流的操作系统。你还需要一个至少有 2GB 大小的 USB 驱动器。",-1))]),t[19]||(t[19]=n('<p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/ubuntu-browse-for-ubuntu-iso.jpg" alt="ubuntu-browse-for-ubuntu-iso" title="ubuntu-browse-for-ubuntu-iso"></p><p>安装好 Etcher 以后，直接打开。点击 <ruby>选择镜像<rt>Select Image</rt></ruby> 按钮来制作镜像。这将提示用户浏览、寻找 ISO 镜像，找到前面下载的 Ubuntu ISO 文件并选择。然后，插入 USB 驱动器，Etcher 应该会自动选择它。之后，点击 “Flash!” 按钮，Ubuntu 启动盘的制作过程就开始了。</p><p>为了能够启动 Ubuntu 系统，需要配置 BIOS。这是必需的，这样计算机才能启动新创建的 Ubuntu 启动盘。为了进入 BIOS，在插入 USB 的情况下重启电脑，然后按正确的键（Del、F2 或者任何和你的电脑相应的键）。找到从 USB 启动的选项，然后启用这个选项。</p><p>如果你的个人电脑不支持 USB 启动，那么把 Ubuntu 镜像刻入 DVD 中。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>当用启动盘第一次加载 Ubuntu 时，欢迎界面会出现两个选项。请选择 “安装 Ubuntu” 选项。在下一页中，Ubiquity 安装工具会请求用户选择一些选项。这些选项不是强制性的，可以忽略。然而，建议两个选项都勾选，因为这样可以节省安装系统以后的时间，特别是安装 MP3 解码器和更新系统。（LCTT 译注：当然如果你的网速不够快，还是不要勾选的好。）</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/ubuntu-preparing-to-install.jpg" alt="ubuntu-preparing-to-install" title="ubuntu-preparing-to-install"></p><p>勾选了<ruby>“准备安装 Ubuntu”<rt>Preparing to install Ubuntu</rt></ruby>页面中的两个选项以后，需要选择安装类型了。有许多种安装类型。然而，这个教程需要选择自定义安装类型。为了进入自定义安装页面，勾选<ruby>“其他”<rt>something else</rt></ruby>选项，然后点击“继续”。</p><p>现在将显示 Ubuntu 自定义安装分区工具。它将显示任何/所有能够安装 Ubuntu 系统的磁盘。如果两个硬盘均可用，那么它们都会显示。如果插有 SD 卡，那么它也会显示。</p><p>选择用于 Root 文件系统的硬盘驱动器。如果上面已经有分区表，编辑器会显示出来，请使用分区工具把它们全部删除。如果驱动没有格式化也没有分区，那么使用鼠标选择驱动器，然后点击<ruby>“新建分区表”<rt>new partition table</rt></ruby>。对所有驱动器执行这个操作，从而使它们都有分区表。（LCTT 译注：警告，如果驱动器上有你需要的数据，请先备份，否则重新分区后将永远丢失。）</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/ubuntu-create-mount-point.jpg" alt="ubuntu-create-mount-point" title="ubuntu-create-mount-point"></p><p>现在所有分区都有了分区表（并已删除分区），可以开始进行配置了。在第一个驱动器下选择空闲空间，然后点击加号按钮来创建新分区。然后将会出现一个“创建分区窗口”。允许工具使用整个硬盘。然后转到<ruby>“挂载点”<rt>Mount Point</rt></ruby>下拉菜单。选择 <code>/</code> （Root）作为挂载点，之后点击 OK 按钮确认设置。</p><p>对第二个驱动器做相同的事，这次选择 <code>/home</code> 作为挂载点。两个驱动都设置好以后，选择要放入引导装载器的驱动器，然后点击 <ruby>“现在安装”<rt>install now</rt></ruby>，安装进程就开始了。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/ubuntu-multi-drive-layout.jpg" alt="ubuntu-multi-drive-layout" title="ubuntu-multi-drive-layout"></p><p>从这以后的安装进程是标准安装。创建用户名、选择时区等。</p><p><strong>注：</strong> 你是以 UEFI 模式进行安装吗？如果是，那么需要给 boot 创建一个 512 MB 大小的 FAT32 分区。在创建其他任何分区前做这件事。确保选择 “/boot” 作为这个分区的挂载点。</p><p>如果你需要一个交换分区，那么，在创建用于 <code>/</code> 的分区前，在第一个驱动器上进行创建。可以通过点击 ‘+’ 按钮，然后输入所需大小，选择下拉菜单中的<ruby>“交换区域”<rt>swap area</rt></ruby>来创建交换分区。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>Linux 最好的地方就是可以自己按需配置。有多少其他操作系统可以让你把文件系统分割在不同的硬盘驱动上？并不多，这是肯定的。我希望有了这个指南，你将意识到 Ubuntu 能够提供的真正力量。</p><p>安装 Ubuntu 系统时你会用多个驱动器吗？请在下面的评论中让我们知道。</p><hr>',21)),a("p",null,[t[6]||(t[6]=e("via: ",-1)),o(u,{href:"https://www.maketecheasier.com/install-ubuntu-with-different-root-home-hard-drives/"},{default:r(()=>[...t[5]||(t[5]=[e("https://www.maketecheasier.com/install-ubuntu-with-different-root-home-hard-drives/",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("作者：",-1)),o(u,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:r(()=>[...t[7]||(t[7]=[e("Derrik Diener",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),o(u,{href:"https://github.com/ucasFL"},{default:r(()=>[...t[8]||(t[8]=[e("ucasFL",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),o(u,{href:"https://github.com/jasminepeng"},{default:r(()=>[...t[9]||(t[9]=[e("jasminepeng",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(u,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),o(u,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const w=s(d,[["render",b]]);export{x as __pageData,w as default};
